defmodule JoobQ.WorkflowsTest do
  use ExUnit.Case, async: true

  alias JoobQ.Workflows

  test "a start names the workflow and its input, and the options it is given" do
    assert Workflows.start_body("checkout", %{"sku" => 1}, []) ==
             %{"name" => "checkout", "input" => %{"sku" => 1}}

    body = Workflows.start_body("checkout", nil, id: "order-1", context: %{"t" => 1}, build: "b7")
    assert %{"id" => "order-1", "context" => %{"t" => 1}, "build" => "b7"} = body
    refute Map.has_key?(body, "search_attributes")
  end

  test "a wrong option is named without its value" do
    for {opts, wanted} <- [
          {[id: ""], ~r/:id/},
          {[context: "hunter2"], ~r/:context/},
          {[search_attributes: [1]], ~r/:search_attributes/},
          {[other: 1], ~r/:other/}
        ] do
      error = assert_raise ArgumentError, wanted, fn -> Workflows.start_body("w", nil, opts) end
      refute error.message =~ "hunter2"
    end

    assert_raise ArgumentError, ~r/:workflow/, fn -> Workflows.start_body(:w, nil, []) end
  end

  test "a run id is letters, digits, _ and -: never a dot segment, never out of its segment" do
    assert Workflows.path("order-1_A", "/signal") == "/workflows/order-1_A/signal"

    for id <- [
          "..",
          ".",
          "",
          String.duplicate("a", 201),
          "a b",
          "a/b",
          "a%2Fb",
          "a.b",
          "a" <> "\u0301",
          7
        ] do
      assert_raise ArgumentError, ~r/:id/, fn -> Workflows.path(id) end
      assert_raise ArgumentError, ~r/:id/, fn -> Workflows.start_body("w", nil, id: id) end

      assert_raise ArgumentError, ~r/:id/, fn ->
        Workflows.signal(id, "s", nil, name: :nowhere)
      end
    end
  end

  test "update names and ids, waits, queries and attributes are checked before a call" do
    for {fun, wanted} <- [
          {fn -> Workflows.update("r", "set address", nil, []) end, ~r/:update/},
          {fn -> Workflows.update("r", "set", nil, update_id: "a/b") end, ~r/:update_id/},
          {fn -> Workflows.update("r", "set", nil, wait_ms: -1) end, ~r/:wait_ms/},
          {fn -> Workflows.update("r", "set", nil, other: 1) end, ~r/:other/},
          {fn -> Workflows.query("r", "", []) end, ~r/:query/},
          {fn -> Workflows.upsert_attributes("r", set: "hunter2") end, ~r/:set/},
          {fn -> Workflows.upsert_attributes("r", remove: "x") end, ~r/:remove/},
          {fn -> Workflows.result("r", wait_ms: 25_001) end, ~r/:wait_ms/},
          {fn -> Workflows.history("r", limit: 0) end, ~r/:limit/},
          {fn -> Workflows.history("r", after_seq: -1) end, ~r/:after_seq/},
          {fn -> Workflows.update("r", "set", nil, wait_ms: 99) end, ~r/:wait_ms/},
          {fn -> Workflows.update("r", "set", nil, wait_ms: 30_001) end, ~r/:wait_ms/},
          {fn -> Workflows.update("r", "set", nil, update_id: String.duplicate("u", 65)) end,
           ~r/:update_id/},
          {fn -> Workflows.history("r", limit: 201) end, ~r/:limit/},
          {fn -> Workflows.history("r", after_seq: 10_000_001) end, ~r/:after_seq/},
          {fn -> Workflows.upsert_attributes("r", set: Map.new(1..65, &{"a#{&1}", 1})) end,
           ~r/:set/},
          {fn -> Workflows.upsert_attributes("r", set: %{1 => "hunter2"}) end, ~r/:set/},
          {fn -> Workflows.upsert_attributes("r", remove: [1]) end, ~r/:remove/},
          {fn -> Workflows.upsert_attributes("r", remove: ["a" | "b"]) end, ~r/:remove/}
        ] do
      error = assert_raise ArgumentError, wanted, fun
      refute error.message =~ "hunter2"
    end
  end
